import Link from 'next/link'

const projects = [
  { slug: 'acme', name: 'Acme Storefront' },
  { slug: 'orbit', name: 'Orbit Analytics' },
]

export default function Dashboard() {
  return (
    <main>
      <h1>Projects</h1>
      <ul>
        {projects.map((project) => (
          <li key={project.slug}>
            {/* prefetch={true} resolves the cached title (URL/params data) ahead
                of the click so it shows instantly; the details stream in after. */}
            <Link href={`/projects/${project.slug}`} prefetch={true}>
              {project.name}
            </Link>
          </li>
        ))}
      </ul>
    </main>
  )
}

